export function crearNavegacionTeclado(deps){var DOM=deps.DOM;var uiState=deps.uiState;var render=deps.render;var getEstado=deps.getEstado;var setEstado=deps.setEstado;var getPLANO=deps.getPLANO;function manejarTecladoGlobal(e){if(e.key==="Escape"){var estadoActual=getEstado();if(estadoActual&&estadoActual.sesion.curaduriaActiva){setEstado(getPLANO().aplicarAccion(estadoActual,"salirCuraduria"));getPLANO().guardarEstado(getEstado());uiState.paginaTarjetas=1;render();e.preventDefault()}return}if((e.ctrlKey||e.metaKey)&&e.key==="k"){if(DOM.inputBuscar){DOM.inputBuscar.focus();e.preventDefault()}return}if(e.altKey&&e.key==="l"){var primerChip=DOM.listaRubros&&DOM.listaRubros.querySelector("[data-rubro]");if(primerChip){primerChip.focus();e.preventDefault()}return}}function inicializar(){document.addEventListener("keydown",manejarTecladoGlobal)}return{inicializar:inicializar,_handlers:{manejarTecladoGlobal:manejarTecladoGlobal}}}